import 'package:flutter_screenutil/flutter_screenutil.dart';extension IntegerExtension on int {  int get crossAxisCountBuilder => (1.sw ~/ this).clamp(1, 5);  int get crossAxisCountLoading => (1.sw ~/ this).clamp(1, 5);  // int get crossAxisCountBigBuilder => (1.sw ~/ 400).clamp(1, 5);  int get mainAxisCount => (1.sh ~/ 150).clamp(1, this).toInt();}